content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-26-group-buy-012

=== 用户原始指令 (query.txt) ===
奶茶拼单卡,整体带氛围背景,左侧主视觉,右边勾选口味,显示已拼X杯的动态数,跳到天气app看下不下雨,读日历取餐时间,快到截单要风险提醒,夜晚倒计时渐变,浅米色底,文字符号当图标,可滚动的列表。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "奶茶拼单卡,整体带氛围背景,左侧主视觉,右边勾选口味,显示已拼X杯的动态数,跳到天气app看下不下雨,读日历取餐时间,快到截单要风险提醒,夜晚倒计时渐变,浅米色底,文字符号当图标,可滚动的列表。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "groupBuy": {
        "joinedCupsText": {
          "type": "string",
          "description": "当前拼单已成团的奶茶杯数展示文本。",
          "sampleValue": "8杯"
        },
        "countdownText": {
          "type": "string",
          "description": "距离拼单截单的短倒计时和风险提示。",
          "sampleValue": "快截单 12分"
        },
        "flavors": [
          {
            "name": {
              "type": "string",
              "description": "第一项可勾选奶茶口味或选项名称。",
              "sampleValue": "三分糖"
            },
            "value": {
              "type": "string",
              "description": "第一项口味选项值。",
              "sampleValue": "sugar30"
            },
            "selected": {
              "type": "boolean",
              "description": "第一项口味是否已勾选。",
              "sampleValue": true
            }
          },
          {
            "name": {
              "type": "string",
              "description": "第二项可勾选奶茶口味或选项名称。",
              "sampleValue": "少冰"
            },
            "value": {
              "type": "string",
              "description": "第二项口味选项值。",
              "sampleValue": "less_ice"
            },
            "selected": {
              "type": "boolean",
              "description": "第二项口味是否已勾选。",
              "sampleValue": true
            }
          }
        ]
      },
      "calendar": {
        "items": [
          {
            "dtStart": {
              "type": "string",
              "description": "当天取餐日程的开始时间，通常为 HH:MM。",
              "sampleValue": "20:30"
            },
            "entityId": {
              "type": "string",
              "description": "取餐日程唯一标识符。",
              "sampleValue": "calendar_pickup_001"
            },
            "title": {
              "type": "string",
              "description": "取餐日程标题。",
              "sampleValue": "奶茶取餐"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/rain.png",
      "description": "天气降雨彩色图标，可作为跳转天气查看是否下雨的候选素材。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，可作为取餐日程时间的候选素材。"
    }
  ]
}

